page_settings.custom_css:
/* Remover espaço em brando lateral no mobile */
html, body{
    overflow-x: hidden !important; 
}

.scale-up-center {
    animation: pisca .5s;
    animation-iteration-count: infinite;
}

@keyframes pisca {
    0% {
        transform: scale(1);
    } 50% {
        transform: scale(1.1);
    } 100% {
        transform: scale(1);
    }
}
